/bin/bash -lc "samtools depth -a donor.bam | python3 -c 'import sys; bs=be=None; nb=0; s=0; blocks=[]
for line in sys.stdin:
 p,d=int(line.split()[1]),int(line.split()[2])
 if d<=0: continue
 if bs is None: bs=be=p; nb=1; s=d
 elif p==be+1: be=p; nb+=1; s+=d
 else:
  if nb>0: blocks.append((bs,be,nb,s/nb))
  bs=be=p; nb=1; s=d
if nb>0: blocks.append((bs,be,nb,s/nb))
for b in blocks:
 if b[2]>=1000: print(*b)' | head -100"

